// moved through their statuses (open, settle, approve, reject with a reason, void, re-settle) from each
// claim's row, and reassigned there to another person.
const PAST: Record<ClaimAction, string> = {
  open: 'opened',
  settle: 'settled',
  approve: 'approved',
  reject: 'rejected',
  void: 'voided',
  resettle: 're-settled',
};

